local UIFishpoolActivityRankDialog = Class("UIFishpoolActivityRankDialog")
local UIFishpoolActivityRankNode = "Game.UI.Fishing.UIFishpoolActivityRankDialog.UIFishpoolActivityRankNode"

function UIFishpoolActivityRankDialog:__init() 
    self._rankData = nil                --排行榜数据
    self._rankMeData = nil              --自己的数据
    self._fishPlaceId = 0
    self._activityId = 0
end

function UIFishpoolActivityRankDialog:__delete()
    self._rankData = nil
    self._rankMeData = nil     
    self._fishPlaceId = nil
    self._activityId = nil  
end

function UIFishpoolActivityRankDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._fishPlaceId = checkNumber(argument.fishPlaceId)    
    self._activityId = FishingUtils.GetFishPlaceActivityId(self._fishPlaceId, ConstantsFishing.ActivityType.Summer)
    if self._activityId == 0 then
        return
    end
    
    SetButtonAction(self.FontStyleButton, function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolActivityRankRewardDialog, parameters = {fishPlaceId = self._fishPlaceId}}, {
            --{id = Constants.UITypeIds.WorldBossPlayerRankingsDialog}
        })
    end)
end

function UIFishpoolActivityRankDialog:FillSelf()
    local isHaveData = #self._rankData > 0

    KTool.SetActive(self.LayoutListAndMyselef, isHaveData)
    KTool.SetActive(self.EmptyNode, not isHaveData)

    if isHaveData then
        self.LoopView:InitListView(#self._rankData, Bind(self, self.OnGetCellByIndex))
        self:FillMeRank()
    end
end

function UIFishpoolActivityRankDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._rankData[index + 1]
    local cell = listView:NewListViewItem("Cell") 
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIFishpoolActivityRankNode)
    if scr then
        scr:Refresh(data, false, self._activityId)
    end

    return cell
end

--绘制自己的排行信息
function UIFishpoolActivityRankDialog:FillMeRank() 
    if not self._rankData then
        return
    --没自己的记录隐藏
    elseif checkNumber(self._rankMeData.rank) <= 0 or checkNumber(self._rankMeData.presentageRank) <= 0 then
        --return
    end
    CfUtils.SetActive(self.MyRanking, true)   
    local scr = CfUtils.GetLuaScr(self.MyRanking, UIFishpoolActivityRankNode)
    if scr then
        scr:Refresh(self._rankMeData, true, self._activityId)
    end
end

function UIFishpoolActivityRankDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isFinish = false
        GameUtils.Request(Interfaces.FishingRank, {placeId = self._fishPlaceId}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
            end
    
            local jsonData = response.data
            self._rankData = checkTable(jsonData.rank)

            local isFind = false
            local playerDojo = comp:GetPlayerDojo()
            for k, v in pairs(self._rankData) do
                if checkNumber(v.playerId) == checkNumber(playerDojo.playerId) then
                    isFind = true
                    self._rankMeData = v
                    break
                end
            end
            if not isFind then
                self._rankMeData = {
                    playerId = playerDojo.playerId,
                    avatar = playerDojo.playerAvatar,
                    avatarFrame = playerDojo.playerAvatarFrame,
                    name = playerDojo.playerName,
                    level = playerDojo.level,
                    presentageRank = checkNumber(jsonData.presentageRank),
                    rank = 0,
                    score = checkNumber(jsonData.myScore),
                    records = checkTable(jsonData.myRecords),
                }
            end

            isFinish = true
        end)

        while not isFinish do
            coroutine.yield(WaitForSeconds(0.01))
        end

        self:FillSelf()
    end))
    return coWait
end

function UIFishpoolActivityRankDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFishpoolActivityRankDialog
